#!/usr/bin/env node
/**
 * Bundled-font source authority transform (issue #601 Step 1).
 *
 * The HarmonyOS Sans SC webfont CSS under apps/web/public/fonts/harmonyos-sans-sc/
 * is generated by cn-font-split (outside this repo). Its default output lists
 * `local(...)` sources BEFORE the bundled `url(...)` in every @font-face, so a
 * host with HarmonyOS Sans SC installed silently renders ITS binary/version
 * instead of the bundled one — the exact cross-host drift the #601 font
 * contract forbids ("bundled product font = primary font authority").
 *
 * This script is the repo-owned regeneration step: after re-running
 * cn-font-split, run this transform to strip every local() source so the
 * bundled WOFF2 is the sole @font-face source. unicode-range splitting keeps
 * downloads chunked, the family name, 400/500/700 faces, font-display and the
 * --font-ui fallback chain are untouched. The invariant is gated by
 * apps/web/src/docs/fontAuthority.test.ts.
 *
 * Usage: node scripts/fonts/bundled-font-sources.mjs [--check]
 *   default  rewrite the HarmonyOS CSS files in place (idempotent)
 *   --check  exit 1 when local() sources are present, without writing
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

export const FONT_CSS_DIR = join(
  import.meta.dirname,
  "..",
  "..",
  "apps",
  "web",
  "public",
  "fonts",
  "harmonyos-sans-sc",
);

/**
 * Pure transform: remove every local(...) source from the @font-face src list.
 * Handles both `src:local(...)`,...,url(...)` (cn-font-split output, no space
 * after the colon) and prettified `src:\n  local(...)` forms. Idempotent.
 */
export function stripLocalFontSources(css) {
  return css.replace(
    /^(\s*src\s*:\s*)([\s\S]*?)(;[^\S\n]*\n)/gm,
    (whole, lead, srcList, tail) => {
      if (!srcList.includes("local(")) return whole;
      const sources = srcList
        .split(",")
        .map((s) => s.trim())
        .filter((s) => s && !s.startsWith("local("));
      return `${lead}${sources.join(", ")}${tail}`;
    },
  );
}

async function main() {
  const checkOnly = process.argv.includes("--check");
  const files = (await readdir(FONT_CSS_DIR))
    .filter((f) => f.endsWith(".css"))
    .sort();
  let dirty = false;
  for (const file of files) {
    const path = join(FONT_CSS_DIR, file);
    const css = await readFile(path, "utf8");
    const stripped = stripLocalFontSources(css);
    if (stripped === css) continue;
    dirty = true;
    if (checkOnly) {
      console.error(`NEEDS-TRANSFORM: ${file} still declares local() sources`);
      continue;
    }
    await writeFile(path, stripped);
    console.log(`transformed: ${file}`);
  }
  if (checkOnly && dirty) process.exit(1);
  console.log(
    checkOnly
      ? "bundled font sources OK (no local() precedence)"
      : "bundled font sources normalized",
  );
}

if (import.meta.url === `file://${process.argv[1]}`) {
  await main();
}
